function runAway(){if(Math.random()<.75){endBattle('You slipped away safely.');return;}battle.message=`${battle.wild.name} blocks the path!`;battle.phase='message';battleTimer=42;}
function useBerry(){if(!party.length){battle.message='No companion to heal.';battle.phase='message';battleTimer=40;return;}if(berries<=0){battle.message='You are out of berries.';battle.phase='message';battleTimer=40;return;}let p=party[0];if(p.hp>=p.max){battle.message=`${p.name} is already feeling great.`;battle.phase='message';battleTimer=40;return;}berries--;p.hp=Math.min(p.max,p.hp+10);battle.message=`A berry restored ${p.name}'s energy!`;battle.phase='message';battleTimer=48;}
function confirm(){if(state==='dialog'){dialogIndex++;if(dialogIndex>=dialogue.length){state='field';if(dialogueAfter){let fn=dialogueAfter;dialogueAfter=null;fn();}}return;}if(state==='field'){const tx=player.x+(player.dir==='right'?1:player.dir==='left'?-1:0),ty=player.y+(player.dir==='down'?1:player.dir==='up'?-1:0);if(tx===25&&ty===19){startDialog(['Professor Fern: Welcome to Cloverfield!','The tall grass is full of curious little friends.','Find one, then toss a berry when it is tired.','I left three berries in your satchel. Safe travels!'],()=>{if(!party.length){party.push({...creatures[0],hp:creatures[0].max,level:1});toast='Mosskip joined your team!';toastUntil=180;}});return;}if(tx===24&&ty===22){startDialog(['A wooden sign reads:','CLOVERFIELD PATH — follow the creek north.','Tall grass rustles with wildbound friends.']);return;}return;}if(state==='menu'){menuSelect();return;}if(state==='battle'){battleAction();}}
function battleAction(){if(battle.phase==='message'){battle.phase='choose';battle.menu=0;return;}if(battle.phase==='win'){endBattle(battle.message);return;}if(battle.phase!=='choose')return;switch(battle.menu){case 0:attack();break;case 1:catchWild();break;case 2:useBerry();break;case 3:runAway();break;}}
function back(){if(state==='menu'){state='field';return;}if(state==='battle'){if(battle.phase==='choose')runAway();else if(battle.phase==='message')battleAction();return;}if(state==='field'){state='menu';menuIndex=0;menuPage=0;}}
function menuSelect(){if(menuIndex===0){if(!party.length)startDialog(['Your team is empty.','Talk to Professor Fern beside the cottage to begin your journey.']);else startDialog(party.map((p,i)=>`${i+1}. ${p.name}  HP ${p.hp}/${p.max}  · Lv.${p.level||1}`));}else if(menuIndex===1){startDialog([`Satchel: ${berries} field berries.`,`Berries restore 10 energy in a battle.`]);}else if(menuIndex===2){startDialog(['Move with WASD or the arrow keys.','Press Enter / Space to interact.','Press I or Escape for your field journal.']);}else state='field';}
