function drawDialog(){ctx.fillStyle='#19291e77';ctx.fillRect(0,0,W,H);box(10,184,460,76,'#f5e9c9','#273e33',6);let line=dialogue[dialogIndex]||'';text(line,23,199,9,colors.ink);text('A  ·  CONTINUE',451,241,7,'#647253','right');}
function drawMenu(){ctx.fillStyle='#15261f66';ctx.fillRect(0,0,W,H);box(132,38,216,195,'#f3e8c9','#293e34',7);text('FIELD JOURNAL',240,51,10,'#52694d','center');text('CLOVERFIELD  ·  ROUTE 01',240,67,6,'#8a8060','center');let opts=['Companions','Satchel','How to play','Return'];opts.forEach((v,i)=>{let y=91+i*29;box(151,y,178,23,menuIndex===i?'#e7d4a0':'#efe2c1',menuIndex===i?'#a97045':'#b6ad89',4);text((menuIndex===i?'✦ ':'  ')+v,163,y+7,8,menuIndex===i?'#593f31':colors.ink);});text('↑ ↓ CHOOSE   ENTER OPEN   ESC CLOSE',240,214,6,'#6c7158','center');}
function drawToast(){if(toast&&toastUntil>0){box(102,222,276,34,'#f4e8c8','#34483a',5);text(toast,240,234,7,colors.ink,'center');}}
function render(){ctx.clearRect(0,0,W,H);if(state==='battle'){drawBattle();}else{drawWorld();drawHUD();if(state==='dialog')drawDialog();if(state==='menu')drawMenu();drawToast();}if(state==='field'&&party.length===0){/* Professor is the first guide; keep the route uncluttered. */}}

