 function catchWild(){if(!battle||battle.phase!=='choose')return;if(berries<=0){battle.message='No berries left!';battle.phase='message';battleTimer=42;battle.returnFoe=true;return;}berries--;let chance=.38+(1-battle.wild.hp/battle.wild.max)*.48;if(Math.random()<chance){const caught={...battle.wild,hp:battle.wild.max};if(party.length<4){party.push(caught);battle.message=`${caught.name} joined your field team!`;}else{battle.message=`${caught.name} was noted, but your team is full.`;}battle.phase='win';battleTimer=62;battle.returnFoe=false;}else{battle.message=`${battle.wild.name} wriggled free!`;battle.phase='message';battleTimer=45;battle.returnFoe=true;}}
