 function useBerry(){if(!party.length){battle.message='No companion to heal.';battle.phase='message';battleTimer=40;battle.returnFoe=true;return;}if(berries<=0){battle.message='You are out of berries.';battle.phase='message';battleTimer=40;battle.returnFoe=true;return;}let p=party[0];if(p.hp>=p.max){battle.message=`${p.name} is already feeling great.`;battle.phase='message';battleTimer=40;battle.returnFoe=true;return;}berries--;p.hp=Math.min(p.max,p.hp+10);battle.message=`A berry restored ${p.name}'s energy!`;battle.phase='message';battleTimer=48;battle.returnFoe=true;}
