 function battleAction(){if(battle.phase==='message'){if(battle.returnFoe)foeTurn();else{battle.phase='choose';battle.menu=0;}return;}if(battle.phase==='foeMessage'){if(party.length&&party[0].hp<=0){party[0].hp=party[0].max;endBattle(`${party[0].name} rested up at the field station.`);}else{battle.phase='choose';battle.menu=0;}return;}if(battle.phase==='win'){endBattle(battle.message);return;}if(battle.phase!=='choose')return;switch(battle.menu){case 0:attack();break;case 1:catchWild();break;case 2:useBerry();break;case 3:runAway();break;}}

